private static Class<?> resolveArgument(Type typeArgument, Class<?> targetType) {
    if (typeArgument instanceof Class) {
        return (Class<?>) typeArgument;
    } else if (typeArgument instanceof TypeVariable) {
        Type resolvedType = resolveTypeVariable((TypeVariable<?>) typeArgument, targetType);
        if (resolvedType instanceof Class) {
