    if (path.isEmpty()) {
        pathSegments.add(new PathSegmentImpl("", null));
        return pathSegments;
    }

    int start = 0;
    int end = 0;
    if (path.startsWith("/")) {
        start = 1;
    }
    while (end < path.length() - 1) {
        end = path.indexOf('/', start);
        if (end == -1) {
            end = path.length();
        }
        pathSegments.add(new PathSegmentImpl(path.substring(start, end), null));
        start = end + 1;
    }

    if (decode) {
        try {
            for (int i = 0; i < pathSegments.size(); i++) {
                PathSegmentImpl segment = pathSegments.get(i);
