/** Computes a minimal separator of an edge {@code e} in a graph {@code G}.
 * A minimal separator is a set of minimum size that still separates {@code e} from the rest of the graph.
 * @param e the edge to compute a minimal separator of
 * @param G the graph containing the edge {@code e}
 * @return a minimal separator of edge {@code e} as a list of integers
 */
public List<Pair<Integer, Integer>> computeMinimalSeparator(E e, UG graph) {
    /*
    Idea: Breadth-first search from one endpoint of e to the other,
    keeping track of the vertices on the path from the first endpoint to the second.
    The stopping condition is when the current vertex is the second endpoint of e.
    The vertices on the path form the minimal separator.
    */
    // Start with the first endpoint of e
    int v = e.getFirst();
    int w;
    // While the current vertex is not the second endpoint of e
    while (graph.getEdge(v, w) == null) {
        // Add the current vertex to the separator
        List<Integer> separator = new ArrayList<>();
        separator.add(v);
        // Get the neighbors of the current vertex
        List<Integer> neighbors = new ArrayList<>();
        for (E neighbor : graph.edgesOf(v)) {
            if (neighbor.either() != v && neighbor.other() != w) {
                neighbors.add(neighbor.other());
            }
        }
        // Sort the neighbors by the number of neighbors they have in the graph
        Collections.sort(neighbors, new Comparator<Integer>() {
            @Override
            public int compare(Integer o1, Integer o2) {
                return graph.edgesOf(o1).size() - graph.edgesOf(o2).size();
            }
        });
        // Pick the neighbor with the least number of neighbors and make it the current vertex
        v = neighbors.get(0);
    }
    // Add the second endpoint of e to the separator
    separator.add(w);
    return separator;
}

